insert into curriculum_topics values ('P4-french-language-t3-w2','ng-scheme-2025-preprimary-primary','P4','french-language',3,'2',2,'teaching',null,'Compter de 0 à 20 (Counting from 0 to 20) - Part 2','[" Numbers 11-20:  onze (11), douze (12), treize (13), quatorze (14), quinze (15), seize (16), dix-sept (17), dix-huit (18), dix-neuf (19), vingt (20)  Counting from 0 to 20 fluently  Asking \"Combien?\" (How many?): Combien de livres? (How many books?)  Using numbers in context: J''ai quinze ans (I am 15 years old), Il y a dix élèves (There are 10 students)  Number games: counting relay, number bingo"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,841) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w3','ng-scheme-2025-preprimary-primary','P4','french-language',3,'3',3,'teaching',null,'Dire l''heure (Telling Time) - Part 1','[" Introduction to time vocabulary:", "L''heure (time/hour), Quelle heure est-il? (What time is it?)", "Il est... heures (It is... o''clock)  Telling time on the hour: Il est une heure (It''s 1 o''clock), Il est deux heures (It''s 2 o''clock), etc.  Parts of the day: le matin (morning), l''après-midi (afternoon), le soir (evening), la nuit (night)  Simple time statements: Il est huit heures du matin (It''s 8 o''clock in the morning)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,841) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w4','ng-scheme-2025-preprimary-primary','P4','french-language',3,'4',4,'teaching',null,'Dire l''heure (Telling Time) - Part 2','[" Telling time with half hours and quarters:", "Et demie (half past): Il est deux heures et demie (It''s 2:30)", "Et quart (quarter past): Il est trois heures et quart (It''s 3:15)", "Moins le quart (quarter to): Il est quatre heures moins le quart (It''s 3:45)  Asking and telling time in dialogues  Daily routines with time: Je me réveille à sept heures (I wake up at 7 o''clock)  Creating daily schedules in French"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,841) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w5','ng-scheme-2025-preprimary-primary','P4','french-language',3,'5',5,'midterm_assessment',null,'Mid-term Examination','[" Assessment of Weeks 1-4"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,842) on conflict (id) do nothing;
