insert into curriculum_topics values ('P4-french-language-t3-w7','ng-scheme-2025-preprimary-primary','P4','french-language',3,'7',7,'teaching',null,'Identifier les aliments et les repas (Identifying Foods and Meals)','["Part 1", " Meals vocabulary:", "Le petit-déjeuner (breakfast), Le déjeuner (lunch), Le dîner (dinner)", "Le repas (meal), Manger (to eat), Boire (to drink)  Common foods:", "Le pain (bread), Le riz (rice), La viande (meat), Le poisson (fish)", "Les fruits (fruits): la banane (banana), l''orange (orange), la pomme (apple)", "Les légumes (vegetables): la tomate (tomato), la carotte (carrot)  Simple sentences: Je mange du pain (I eat bread)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,842) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w8','ng-scheme-2025-preprimary-primary','P4','french-language',3,'8',8,'teaching',null,'Identifier les aliments et les repas (Identifying Foods and Meals)','["Part 2", " More food vocabulary:", "Drinks: l''eau (water), le jus (juice), le lait (milk), le thé (tea)", "Other foods: les œufs (eggs), le fromage (cheese), le gâteau (cake)", "Nigerian foods in French: le garri, le fufu, le jollof rice  Expressing likes and dislikes: J''aime... (I like...), Je n''aime pas... (I don''t like...)  Meal times: Je prends le petit-déjeuner à sept heures (I have breakfast at 7 o''clock)  Food-related verbs: manger (to eat), boire (to drink), prendre (to take/have)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,842) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w9','ng-scheme-2025-preprimary-primary','P4','french-language',3,'9',9,'teaching',null,'Identifier les aliments et les repas (Identifying Foods and Meals)','["Part 3", " At the market/restaurant vocabulary:", "Je voudrais... (I would like...), S''il vous plaît (Please)", "Combien ça coûte? (How much does it cost?), C''est combien? (How much is it?)  Quantities: un peu de (a little), beaucoup de (a lot of), un kilo de (a kilo of)  Table manners vocabulary: Bon appétit! (Enjoy your meal!)  Role-play: ordering food, buying at market  Creating menus in French"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,842) on conflict (id) do nothing;
insert into curriculum_topics values ('P4-french-language-t3-w10','ng-scheme-2025-preprimary-primary','P4','french-language',3,'10',10,'teaching',null,'Review and Integration: Human Activities Theme','[" Comprehensive review of counting, time, and food vocabulary  Creating daily schedules with times and meals in French  Market/restaurant role-plays  Counting and shopping scenarios  Food preferences presentations: Mon repas préféré (My favorite meal)  French language games: time bingo, food matching, counting challenges  Songs about numbers, time, and food"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,843) on conflict (id) do nothing;
