insert into curriculum_topics values ('P6-christian-religious-studies-t3-w7','ng-scheme-2025-preprimary-primary','P6','christian-religious-studies',3,'7',7,'teaching',null,'Temptation and Corruption I','["Understanding temptation - meaning and sources; Temptation is not sin (Hebrews 4:15); Sources of temptation - the devil, the world, the flesh (1 John 2:15-17); Jesus'' temptation in the wilderness (Matthew 4:1-11); Common temptations for young people - lying, cheating, stealing, disobedience, immorality, pride; How temptation works (James 1:13-15)"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,923) on conflict (id) do nothing;
insert into curriculum_topics values ('P6-christian-religious-studies-t3-w8','ng-scheme-2025-preprimary-primary','P6','christian-religious-studies',3,'8',8,'teaching',null,'Temptation and Corruption II','["Resisting temptation - prayer (Matthew 26:41), Word of God (Psalm 119:11), flee from temptation (1 Corinthians 6:18, 2 Timothy 2:22), accountability and fellowship; Joseph resisting Potiphar''s wife (Genesis 39:7-12); God provides a way of escape (1 Corinthians 10:13); Victory through Christ; Building spiritual strength"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,923) on conflict (id) do nothing;
insert into curriculum_topics values ('P6-christian-religious-studies-t3-w9','ng-scheme-2025-preprimary-primary','P6','christian-religious-studies',3,'9',9,'teaching',null,'Corruption I','["Understanding corruption - meaning, types, forms; Biblical teaching against corruption - bribes (Exodus 23:8), dishonest gain (Proverbs 15:27), theft (Exodus 20:15); Examples of corruption in the Bible", "Gehazi (2 Kings 5:20-27), Judas (Matthew 26:14-16), Ananias and Sapphira (Acts 5:1-11); Consequences of corruption"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,924) on conflict (id) do nothing;
