insert into curriculum_topics values ('P6-french-language-t3-w1','ng-scheme-2025-preprimary-primary','P6','french-language',3,'1',1,'teaching',null,'Activités - Les Métiers et Les Professions Détaillés','["Professions vocabulary - le médecin, l''infirmier/l''infirmière, l''enseignant(e), l''ingénieur, l''avocat(e), le policier, le pompier, le pilote, le chauffeur, le cuisinier/la cuisinière, l''agriculteur/l''agricultrice, le commerçant(e); Asking about professions", "Que fait ton père/ta mère? Qu''est-ce que tu veux devenir?; Future aspirations", "Je veux être..., Je voudrais devenir"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,956) on conflict (id) do nothing;
insert into curriculum_topics values ('P6-french-language-t3-w2','ng-scheme-2025-preprimary-primary','P6','french-language',3,'2',2,'teaching',null,'Activités','["Parler de Ses Projets Futurs (Introduction au Futur Proche)", "Future tense introduction using \"aller\"", "Je vais..., Tu vas..., Il/Elle va...; Expressing future plans", "Demain, je vais..., La semaine prochaine...; Holiday plans", "Pendant les vacances, je vais...; Projects and goals", "Je vais étudier..., Je vais visiter...; Time expressions for future"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,956) on conflict (id) do nothing;
