-- Curriculum data: Part 5 of 5. Run the parts in order.

-- Security rules (Row Level Security)
-- Master curriculum: any signed-in user can read it; nobody can change it from the app.
alter table curricula              enable row level security;
alter table class_levels           enable row level security;
alter table subjects               enable row level security;
alter table curriculum_offerings   enable row level security;
alter table curriculum_topics      enable row level security;
alter table resource_providers     enable row level security;

create policy "Signed-in users can read curricula"          on curricula            for select to authenticated using (true);
create policy "Signed-in users can read class levels"       on class_levels         for select to authenticated using (true);
create policy "Signed-in users can read subjects"           on subjects             for select to authenticated using (true);
create policy "Signed-in users can read offerings"          on curriculum_offerings for select to authenticated using (true);
create policy "Signed-in users can read curriculum topics"  on curriculum_topics    for select to authenticated using (true);
create policy "Signed-in users can read resource providers" on resource_providers   for select to authenticated using (true);

-- School data: locked for now. Rules that limit each school to its own records
-- are added once logins and the schools/staff tables exist.
alter table digital_resources        enable row level security;
alter table topic_resources          enable row level security;
alter table school_subject_settings  enable row level security;
alter table school_topic_overrides   enable row level security;
alter table lesson_notes             enable row level security;
alter table topic_coverage           enable row level security;

-- The coverage report follows the same rules as the tables it reads from.
alter view coverage_summary set (security_invoker = true);
